-- ============================================
-- LUMA — Thème 9 : MOYEN 2/3 x4 — Négocier avec un dragon plutôt que combattre
-- ============================================


update scenarios set content = '{"characters": {"dragon": "le dragon"}, "start_node": "n1", "nodes": {"n1": {"speaker": "dragon", "text": "(A massive dragon opens one eye) Another fool seeking my hoard, I presume?", "text_fr": "(Un dragon massif ouvre un œil) Un autre fou cherchant mon trésor, je présume ?", "choices": [{"text": "Actually, great one, I come seeking wisdom, not gold.", "text_fr": "En fait, grand dragon, je viens chercher la sagesse, pas l''or.", "next": "n2"}, {"text": "I''ve heard tales of your magnificence, and wished to see it for myself.", "text_fr": "J''ai entendu des récits de votre magnificence, et je voulais la voir par moi-même.", "next": "n2b"}]}, "n2": {"speaker": "dragon", "text": "(Raises an eyebrow scale) Wisdom? How refreshingly unusual. Continue.", "text_fr": "(Lève une écaille-sourcil) La sagesse ? Quelle nouveauté rafraîchissante. Continuez.", "choices": [{"text": "They say dragons remember things no one else does — history, magic, truth.", "text_fr": "On dit que les dragons se souviennent de choses que personne d''autre ne connaît — l''histoire, la magie, la vérité.", "next": "n3"}]}, "n2b": {"speaker": "dragon", "text": "(Preens slightly despite itself) Flattery. How delightfully predictable, yet effective.", "text_fr": "(Se lisse les écailles malgré lui) De la flatterie. Comme c''est délicieusement prévisible, et pourtant efficace.", "choices": [{"text": "It''s not flattery if it''s true, noble dragon.", "text_fr": "Ce n''est pas de la flatterie si c''est vrai, noble dragon.", "next": "n3"}]}, "n3": {"speaker": "dragon", "text": "(Considers) You speak differently than the usual sword-swinging fools. What do you truly seek?", "text_fr": "(Réfléchit) Vous parlez différemment des habituels fous brandisseurs d''épée. Que cherchez-vous vraiment ?", "choices": [{"text": "Knowledge of an ancient prophecy, said to be etched somewhere in your lair.", "text_fr": "Le savoir d''une ancienne prophétie, dite être gravée quelque part dans votre antre.", "next": "n4"}, {"text": "Guidance. My kingdom faces a threat, and legends say dragons once helped mortals.", "text_fr": "Des conseils. Mon royaume fait face à une menace, et les légendes disent que les dragons ont autrefois aidé les mortels.", "next": "n4"}]}, "n4": {"speaker": "dragon", "text": "(Long pause) The prophecy you speak of... yes, I know it well. Few do anymore.", "text_fr": "(Longue pause) La prophétie dont vous parlez... oui, je la connais bien. Peu la connaissent encore.", "choices": [{"text": "Would you be willing to share what you know, great one?", "text_fr": "Seriez-vous prêt à partager ce que vous savez, grand dragon ?", "next": "n5"}]}, "n5": {"speaker": "dragon", "text": "(Studies you intently) Knowledge is not given freely, even to the well-mannered. What do you offer in return?", "text_fr": "(Vous étudie intensément) Le savoir ne se donne pas librement, même aux bien élevés. Qu''offrez-vous en retour ?", "choices": [{"text": "I have little gold, but I offer my word to use this knowledge only for good.", "text_fr": "J''ai peu d''or, mais j''offre ma parole d''utiliser ce savoir seulement pour le bien.", "next": "n6"}, {"text": "What would you ask of me, dragon? Name your price.", "text_fr": "Que me demanderiez-vous, dragon ? Nommez votre prix.", "next": "n6b"}]}, "n6": {"speaker": "dragon", "text": "(Chuckles, smoke curling from nostrils) A promise, freely given. How rare, how honest.", "text_fr": "(Ricane, fumée s''échappant des narines) Une promesse, librement donnée. Comme c''est rare, comme c''est honnête.", "choices": [{"text": "I mean every word of it, dragon.", "text_fr": "Je pense chaque mot, dragon.", "next": "n7"}]}, "n6b": {"speaker": "dragon", "text": "(Considers) A favor, then — someday, when I call upon you, you must answer.", "text_fr": "(Réfléchit) Une faveur, alors — un jour, quand je vous appellerai, vous devrez répondre.", "choices": [{"text": "That''s a fair exchange. I accept your terms, dragon.", "text_fr": "C''est un échange juste. J''accepte vos conditions, dragon.", "next": "n7"}]}, "n7": {"speaker": "dragon", "text": "(Nods slowly) Very well. Come closer, and I shall share what the ancients once knew.", "text_fr": "(Hoche lentement la tête) Très bien. Approchez, et je partagerai ce que les anciens savaient autrefois.", "choices": [{"text": "(Step closer, listening intently to the dragon''s ancient wisdom.)", "text_fr": "(Approche-toi, écoutant attentivement la sagesse ancienne du dragon.)", "next": "n8"}]}, "n8": {"speaker": "dragon", "text": "(Recounts an ancient tale, revealing crucial knowledge about the prophecy''s true meaning.)", "text_fr": "(Raconte un ancien récit, révélant un savoir crucial sur le vrai sens de la prophétie.)", "choices": [{"text": "This changes everything. Thank you, truly, great dragon.", "text_fr": "Ça change tout. Merci, vraiment, grand dragon.", "next": "n9"}]}, "n9": {"speaker": "dragon", "text": "Go now, and remember — not all power lies in claws and fire. Some lies in wisdom, and patience.", "text_fr": "Allez maintenant, et souvenez-vous — tout le pouvoir ne réside pas dans les griffes et le feu. Certains résident dans la sagesse, et la patience.", "choices": [{"text": "I''ll carry your words with me always, dragon. Farewell.", "text_fr": "Je porterai vos mots avec moi toujours, dragon. Adieu.", "next": "end_wisdom"}]}, "end_wisdom": {"speaker": "dragon", "text": "Farewell, wise one. Perhaps our paths shall cross again.", "text_fr": "Adieu, sage voyageur. Peut-être nos chemins se croiseront-ils à nouveau.", "end": true, "ending_label": "Sagesse gagnée sans combat, par le respect 🐉📜"}}}'::jsonb, is_playable = true
where title = 'Négocier avec un dragon plutôt que combattre'
  and theme_id = (select id from scenario_themes where position = 9 and language_id = (select id from languages where code = 'en'));
